"""Generate the public audit from an explicit allowlist of non-secret test data."""
from pathlib import Path
import argparse,csv,hashlib,html,json,math,shutil,statistics,sys
from sacrebleu.metrics import CHRF,BLEU
ROOT=Path(__file__).resolve().parents[1]
MODELS={'cpu':'OPUS-MT / CPU','cuni-q3km':'CUNI-MH 7B Q3_K_M','translategemma-4b-q4km':'TranslateGemma 4B Q4_K_M','gpt-6-luna':'OpenAI GPT-6 Luna · none'}
def read(path):return [json.loads(x) for x in path.read_text('utf-8').splitlines()]
def quantile(values,q):return sorted(values)[max(0,math.ceil(len(values)*q)-1)]
def main():
    p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--partial',action='store_true');a=p.parse_args();run=a.run.resolve();bench=run/'benchmark500'
    web=ROOT/'website/runs/2026-11-23-api500';data=web/'data';data.mkdir(parents=True,exist_ok=True)
    cases=read(bench/'dataset500.jsonl');assert len(cases)==500 and len({r['en'] for r in cases})==500
    results={m:read(bench/(m+'.jsonl')) for m in MODELS};assert all(len(rows)==500 for rows in results.values())
    judges=read(bench/'blind-judge.jsonl') if (bench/'blind-judge.jsonl').exists() else []
    if not a.partial:assert len(judges)==500,'Wait for all 500 judge responses'
    ratings={r['id']:{x['model']:x for x in r.get('ratings',[]) if x.get('model') in MODELS} for r in judges if not r['error']}
    references=[c['reference_cs'] for c in cases];summaries=[];chrf=CHRF(word_order=2);bleu=BLEU()
    combined=[dict(c,models={}) for c in cases];judge_cost=sum(r['estimated_usd'] for r in judges)
    for model,rows in results.items():
        assert [r['id'] for r in rows]==[r['id'] for r in cases]
        times=[r['ms'] for r in rows];ok=[r for r in rows if not r['error']]
        assessed=[ratings[c['id']][model] for c in cases if model in ratings.get(c['id'],{})]
        meaning=statistics.mean(r['meaning'] for r in assessed) if assessed else None
        fluency=statistics.mean(r['fluency'] for r in assessed) if assessed else None
        hypotheses=[r['translation'] for r in rows]
        summary={'model':model,'label':MODELS[model],'requests':len(rows),'valid':len(ok),'errors':len(rows)-len(ok),'mean_ms':statistics.mean(times),'median_ms':statistics.median(times),'p95_ms':quantile(times,.95),'max_ms':max(times),'success_median_ms':statistics.median(r['ms'] for r in ok),'chrf_pp':chrf.corpus_score(hypotheses,[references]).score,'bleu':bleu.corpus_score(hypotheses,[references]).score,'judge_n':len(assessed),'meaning_mean_0_4':meaning,'fluency_mean_0_4':fluency,'critical_count':sum(x['critical'] for x in assessed),'estimated_usd':sum(r.get('estimated_usd',0) for r in rows),'input_tokens':sum(r.get('usage',{}).get('input_tokens',0) for r in rows),'output_tokens':sum(r.get('usage',{}).get('output_tokens',0) for r in rows),'reasoning_tokens':sum(r.get('usage',{}).get('output_tokens_details',{}).get('reasoning_tokens',0) for r in rows)}
        summaries.append(summary)
        for c,row in zip(combined,rows):
            c['models'][model]={**row,'rating':ratings.get(c['id'],{}).get(model),'chrf_pp':chrf.sentence_score(row['translation'],[c['reference_cs']]).score}
    filters=read(run/'api-filter100/results.jsonl') if (run/'api-filter100/results.jsonl').exists() else []
    def fscore(rows):return {'count':len(rows),'dialogue':sum(r['expected']=='KEEP' for r in rows),'dialogue_lost':sum(r['expected']=='KEEP' and r['decision']=='SKIP' for r in rows),'unwanted':sum(r['expected']=='SKIP' for r in rows),'unwanted_removed':sum(r['expected']=='SKIP' and r['decision']=='SKIP' for r in rows),'ambiguous':sum(r['expected']=='UNCERTAIN' for r in rows),'ambiguous_removed':sum(r['expected']=='UNCERTAIN' and r['decision']=='SKIP' for r in rows),'errors':sum(bool(r.get('error')) for r in rows)}
    report={'status':'partial' if len(judges)<500 else 'complete','dataset':json.loads((bench/'dataset-manifest.json').read_text('utf-8')),'hardware':{'cpu':'Intel Core i5-13420H','gpu':'NVIDIA GeForce RTX 4050 Laptop GPU / 6 GiB','os':'Windows 11'},'conditions':{'ocr':False,'frame_generation':False,'enhancer':False,'translation_requests_serial_per_model':True,'local_models_serial':True,'cloud_and_local_runs_overlap':True,'desktop':'Normal user desktop, other applications not forcibly closed. No application build ran during the translation benchmark. API judge and UI tests were started after local translation runs.'},'metric_signatures':{'chrf_pp':str(chrf.get_signature()),'bleu':str(bleu.get_signature())},'models':summaries,'judge':{'model':'gpt-6.1-terra','responses':len(judges),'valid_responses':len(ratings),'estimated_usd':judge_cost,'independent_human':False,'vendor_overlap':True},'filter':fscore(filters),'filter_estimated_usd':sum(r['estimated_usd'] for r in filters),'cases':combined}
    (data/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),'utf-8')
    # Keep full audit data downloadable; the interactive viewer fetches small
    # chunks without repeated token/accounting metadata.
    chunks=[]
    for start in range(0,len(combined),25):
        name=f'viewer-{start//25+1:02d}.json';chunks.append(name)
        compact=[{'id':c['id'],'en':c['en'],'reference_cs':c['reference_cs'],'models':{m:{k:r[k] for k in ['translation','ms','error','rating','chrf_pp']} for m,r in c['models'].items()}} for c in combined[start:start+25]]
        (data/name).write_text(json.dumps(compact,ensure_ascii=False,indent=2),'utf-8')
    (data/'viewer-index.json').write_text(json.dumps({'models':summaries,'chunks':chunks},ensure_ascii=False,indent=2),'utf-8')
    (run/'summary500.json').write_text(json.dumps({k:v for k,v in report.items() if k!='cases'},ensure_ascii=False,indent=2),'utf-8')
    # Deliberately exclude key files, Credential Manager, available-account-model
    # inventory, app preferences, private logs, raw API response IDs and tokens.
    allow=['dataset500.jsonl','dataset-manifest.json','COPYING-wesnoth.txt','blind-judge.jsonl','blind-judge-meta.json']
    allow += [m+suffix for m in MODELS for suffix in ['.jsonl','-meta.json']]
    for name in allow:
        if (bench/name).is_file():shutil.copy2(bench/name,data/name)
    if filters:shutil.copy2(run/'api-filter100/results.jsonl',data/'api-filter100.jsonl')
    for name in ['benchmark_subtitles_500.py','judge_subtitles_500.py','render_api500_report.py','evaluate_api_filter.py']:
        shutil.copy2(ROOT/'tools'/name,data/name)
    with (data/'translations.csv').open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.writer(f);writer.writerow(['id','English','reference_cs','model','translation','ms','error','meaning_0_4','fluency_0_4','critical','judge_note_cs'])
        for c in combined:
            for model,row in c['models'].items():
                score=row['rating'] or {};writer.writerow([c['id'],c['en'],c['reference_cs'],model,row['translation'],round(row['ms'],2),row['error'],score.get('meaning'),score.get('fluency'),score.get('critical'),score.get('note_cs')])
    rows=''.join(f'<tr><th>{html.escape(m["label"])}</th><td>{m["valid"]}/500</td><td>{m["median_ms"]/1000:.2f} s</td><td>{m["p95_ms"]/1000:.2f} s</td><td>{m["chrf_pp"]:.1f}</td><td>{m["meaning_mean_0_4"]:.2f}</td><td>{m["fluency_mean_0_4"]:.2f}</td><td>{m["critical_count"]}/{m["judge_n"]}</td></tr>' for m in summaries if m['meaning_mean_0_4'] is not None)
    api=next(m for m in summaries if m['model']=='gpt-6-luna');fil=report['filter']
    ledger=json.loads((run/'cost-ledger.json').read_text('utf-8')) if (run/'cost-ledger.json').exists() else None
    total_cost=(f'<p><strong>Celá tato zkouška včetně AI hodnocení: přibližně ${ledger["known_estimated_usd"]:.2f}.</strong> Doložený součet je ${ledger["known_estimated_usd"]:.7f}; chybí tokeny jednoho neplatného výstupu. Většinu ceny tvoří dodatečné hodnocení, nikoli samotný překlad. Není to odečet aktuálního zůstatku účtu.</p>' if ledger else '')
    interpretation='''<h2>Co z toho vychází</h2><p>CUNI má v této sadě největší podobnost s lidskou referencí (chrF++), API dostalo od anonymizovaného AI posuzovatele nejvyšší průměr za význam a přirozenost. To nejsou totožná měřítka a posuzovatel je od stejného dodavatele jako API kandidát. CUNI je zde přesvědčivá místní volba pro EN → CS; širší jazyková nabídka TranslateGemma sama nezaručuje lepší češtinu. API šetří místní výpočet překladu, ale na tomto notebooku čekalo déle než oba GPU modely.</p><p>Konkrétní chyby najdeš přes hledání ID: <strong>w500-002</strong> — CPU ztratil „nemrtvé“, Gemma vytvořila gramaticky vadné přání, CUNI a API zachovaly význam. <strong>w500-032</strong> — i API selhalo: „I will put an end…“ změnilo na rozkaz „skoncuj“; CUNI tuto repliku zvládlo. <strong>w500-026</strong> ukazuje subjektivitu skóre: posuzovatel API strhl bod za vynechání nejistoty „may“, přestože česká věta zní přirozeně. Jde o příklady k prohlédnutí, nikoli další nezávislé měření.</p>'''
    page=f'''<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FrameLab — 500 překladů: lokální modely a OpenAI API</title><link rel="stylesheet" href="../../guide/assets/remote-subtitles.css"><style>main{{max-width:1360px}}input,select{{font:inherit;background:#1b2518;color:#edf2e5;border:1px solid #536246;padding:9px;max-width:100%}}.controls{{display:flex;gap:14px;flex-wrap:wrap;align-items:center}}article{{border:1px solid #34402f;padding:20px;margin:20px 0}}.candidates{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}}.candidate{{border-top:1px solid #34402f;padding-top:12px;overflow-wrap:anywhere}}.score{{color:#bbff61;font-size:14px}}.bad{{color:#ff9d7b}}blockquote{{margin:12px 0;padding:10px 16px;border-left:3px solid #6f844e}}.meta{{color:#afbaa5;font-size:14px}}@media(max-width:720px){{.candidates{{grid-template-columns:1fr}}}}button:disabled{{opacity:.35;cursor:default}}.table th{{min-width:100px}}</style></head><body><main><nav><a href="../../?lang=cs">FRAME/LAB</a><a href="../../guide/remote-subtitles.html">Remote Play / jen titulky / API</a><a href="#english">English methodology</a></nav><p class="tag">23. 11. 2026 · 500 STEJNÝCH REPLIK · 4 PŘEKLADAČE</p><h1>Jaká je čeština<br>a kolik stojí čekání?</h1>
    <p class="notice">{'ROZPRACOVANÝ NÁHLED — hodnocení ještě běží. ' if a.partial else ''}<strong>Měříme textový překlad bez OCR, frame genu a enhanceru.</strong> API a místní test běžely souběžně, místní modely postupně. Toto není měření latence hry ani záruka kvality všech jazyků. Nová integrace patří do místního experimentu; veřejný ZIP preview.17 se tímto protokolem nemění.</p>
    <h2>Rychlost a kvalita na stejném zadání</h2><div class="table"><table><thead><tr><th>Model</th><th>Platné výstupy</th><th>Medián</th><th>P95</th><th>chrF++</th><th>Význam / 4</th><th>Čeština / 4</th><th>Závažná chyba*</th></tr></thead><tbody>{rows}</tbody></table></div>
    <p class="small">P95: 95 % požadavků skončilo do této doby; zahrnuje i chyby. chrF++ (0–100) měří podobnost s jednou lidskou referencí, nikoli přímo správnost. Význam, čeština a závažné chyby jsou hodnocení jednoho AI posuzovatele GPT-6.1 Terra. Jména kandidátů neviděl a jejich pořadí bylo pro každou repliku jiné. Není to nezávislý lidský audit; poskytovatel posuzovatele je stejný jako u jednoho kandidáta.</p>
    <h2>Spotřeba API</h2><p>500 pokusů o překlad přes GPT-6 Luna: <strong>${api['estimated_usd']:.6f}</strong> za doložené tokeny, přibližně <strong>2 americké centy</strong>. Doloženo {api['input_tokens']:,} vstupních a {api['output_tokens']:,} výstupních tokenů; reasoning tokeny: {api['reasoning_tokens']}.</p>
    <p>Jedna odpověď měla neplatnou strukturu. První verze testovacího adaptéru u této chyby neuchovala spotřebu, takže částka je doložený mezisoučet, nikoli přesná faktura. Původní chybový řádek zůstává ve výsledcích. Dodatečný diagnostický pokus uspěl a nenahrazuje původní měření. Záznam spotřeby při neplatné odpovědi je v aplikaci opraven.</p>
    <p>Samostatné AI hodnocení všech kandidátů: <strong>${judge_cost:.6f}</strong>. Zkouška 100 případů filtru: <strong>${report['filter_estimated_usd']:.6f}</strong>. Diagnostická a integrační volání jsou uvedena zvlášť v závěrečném účtu; hodnocení není součástí běžného překladu v aplikaci.</p>
    <p class="small">Odhad vychází z vrácených tokenů a veřejných cen Standard ověřených 23. 11. 2026; zahrnuje instrukce, výstup a případné cache-write tokeny, nezahrnuje daně, měnový převod ani jinou aktivitu účtu. Skutečné vyúčtování ověř na API platformě. <a href="https://developers.openai.com/api/docs/models/gpt-6-luna">GPT-6 Luna</a> · <a href="https://developers.openai.com/api/docs/models/gpt-6.1-terra">GPT-6.1 Terra</a>.</p>
    {total_cost}<p><a href="data/cost-ledger.json">Celý cenový účet včetně diagnostiky</a> · <a href="data/REPRODUCE.md">Přesný postup opakování a omezení</a> · <a href="data/audit-source.zip">Zdrojové skripty, prompty a profily</a> · <a href="data/audit-source-manifest.json">Verze a hashe zdrojů</a></p>{interpretation}
    <h2>Umí API odmítnout nápis?</h2><p>Zvláštní zkouška 100 předem vybraných případů používá skutečný lokální předfiltr a API překlad s posouzením textu. Z {fil['unwanted']} jednoznačně nechtěných textů odstranil {fil['unwanted_removed']}; z {fil['dialogue']} replik chybně odstranil {fil['dialogue_lost']}. U {fil['ambiguous']} nejednoznačných příkladů odstranil {fil['ambiguous_removed']}. Chyby požadavků: {fil['errors']}. <a href="data/api-filter100.jsonl">Všechny případy</a>.</p>
    <p>Samotný text neumí spolehlivě rozlišit nápis od stejné věty vyslovené postavou. Nejisté případy proto oddělujeme. Hlavní sada 500 překladů měla filtr vypnutý, aby výsledek neovlivňovalo zahazování textu.</p>
    <h2>Jak test zopakovat</h2><p>Intel Core i5-13420H, RTX 4050 Laptop GPU 6 GiB, Windows 11. Každý překladač dostal všech 500 stejných anglických replik, postupně a bez historie sousedních vět. API dostávalo pouze text. Lokální runtime při načítání provádí zahřátí; jeho inicializace je samostatně v metadatech. První API požadavek je zahrnutý. Běžící desktop nebyl izolované laboratorní prostředí.</p>
    <p>Sada je pevný výběr z české lokalizace hry <a href="https://github.com/wesnoth/wesnoth/blob/a015f4a5c629c0eb45ac5f115595113c9880e4af/po/wesnoth-httt/cs.po">Battle for Wesnoth</a>: 500 různých položek dialogu z 809 způsobilých, seed 20261123. Vynechány fuzzy překlady, markup a proměnné; délka 5–280 znaků. Lidský překlad slouží jako reference, ale není jedinou správnou formulací. Materiál je veřejný a mohl být v trénovacích datech. Žánr fantasy a chybějící kontext omezují zobecnitelnost. <a href="data/COPYING-wesnoth.txt">Licence GPL</a>; autory české lokalizace uvádí zdrojový PO soubor.</p>
    <p><a href="data/translations.csv">Stáhnout všech 2 000 překladů v CSV</a> · <a href="data/report.json">Úplná data JSON</a> · <a href="data/dataset-manifest.json">Zdroj, výběr a hash datasetu</a> · <a href="data/benchmark_subtitles_500.py">Testovací skript</a> · <a href="data/judge_subtitles_500.py">Prompt a skript hodnocení</a> · <a href="data/blind-judge-meta.json">Nastavení posuzovatele</a> · <a href="data/SHA256SUMS.txt">Kontrolní součty</a></p>
    <h2 id="english">English methodology</h2><p>500 fixed, unique EN→CS game dialogue entries with existing human localization references; four translators, serial requests per model. No OCR, frame generation or enhancement in this benchmark. API and local runs overlapped; local models ran one at a time. Latency includes synchronous translation/network work, not subtitle observation or display delay. chrF++ measures reference similarity. Meaning/fluency scores come from one blinded GPT-6.1 Terra judge with randomized candidate order, not independent human validation. A failed structured API response remains in the dataset and its missing usage is disclosed. Prices are token-based estimates, not account invoices. Public game data may have appeared in training.</p>
    <h2>Prohlédni si každou repliku</h2><div class="controls"><label>Hledat <input id="search" type="search" placeholder="anglicky nebo česky"></label><label>Model <select id="model"><option value="">Všechny čtyři</option>{''.join(f'<option value="{m}">{html.escape(name)}</option>' for m,name in MODELS.items())}</select></label><label><input id="critical" type="checkbox"> jen závažné chyby podle AI</label><label><input id="errors" type="checkbox"> jen chyby požadavků</label></div><p id="count" role="status">Načítám data…</p><div class="controls"><button id="prev">← Předchozí</button><button id="next">Další →</button></div><div id="cases"></div><script src="report.js"></script></main></body></html>'''
    (web/'index.html').write_text(page,'utf-8')
    shutil.copy2(ROOT/'tools/api500_report.js',web/'report.js')
    files=sorted(p for p in data.iterdir() if p.is_file() and p.name!='SHA256SUMS.txt')
    (data/'SHA256SUMS.txt').write_text(''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+p.name+'\n' for p in files),'utf-8')
    print(json.dumps({'judge_rows':len(judges),'models':summaries,'filter':fil,'judge_usd':judge_cost},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
